const $=s=>document.querySelector(s);
const services=[{name:'Customer experience',icon:'◌',tag:'Every customer, heard.',desc:'Helpful conversations across voice, chat, and email. AI handles repeat questions; your Frontline team owns the moments that need care.',tasks:['Customer questions & order support','After-hours answering & overflow','Omnichannel inbox management','Escalation, follow-up & quality review'],flow:['Understand the request','Resolve or route','Confirm the next step']},{name:'Sales & intake',icon:'◈',tag:'Turn interest into action.',desc:'Keep opportunities moving from first contact to a useful next step, with consistent qualification and thoughtful follow-up.',tasks:['Lead qualification & intake','Appointment setting & reminders','Missed-opportunity recovery','Structured sales handover'],flow:['Capture the inquiry','Qualify the opportunity','Schedule & hand over']},{name:'Back office',icon:'▤',tag:'Keep the work moving.',desc:'Give your team more time for the decisions that matter. Manage the administrative work behind every customer interaction.',tasks:['Data entry & organization','Document processing & review','Order & workflow coordination','Exception routing'],flow:['Receive & validate','Process to your rules','Review exceptions']},{name:'IT support',icon:'⌘',tag:'Get people back to work.',desc:'A clear first line for technical questions, with structured diagnosis and escalation to the right specialist.',tasks:['Help desk intake','Guided troubleshooting','Ticket triage & status updates','Escalation with context'],flow:['Identify the issue','Guide & troubleshoot','Escalate with context']}];
const industries={home:{name:'Home services',label:'Built for the calls you can’t miss.',desc:'From the first service request to the technician’s next appointment. Keep intake organized, even when your team is on a job.',examples:['Check service area and request type','Collect details for the dispatcher','Request an appointment or callback','Route urgent issues using your rules'],scenario:'A homeowner needs an after-hours plumbing visit.'},saas:{name:'Software & SaaS',label:'Support that keeps pace with your product.',desc:'Give customers a useful answer and your specialists a clear picture of what needs attention.',examples:['Answer product and account FAQs','Capture steps to reproduce an issue','Route tickets by expertise','Follow up to resolution'],scenario:'A customer needs help accessing their workspace.'},commerce:{name:'Ecommerce',label:'Every order deserves a clear answer.',desc:'Help shoppers before and after checkout, with consistent support across their preferred channels.',examples:['Guide product and policy questions','Collect order information securely','Coordinate returns and delivery requests','Escalate exceptions with history'],scenario:'A shopper wants to understand the return process.'},professional:{name:'Professional services',label:'A first impression worth keeping.',desc:'Make it easy to ask a question, explain a need, and take the next step with your team.',examples:['Answer service questions','Qualify the scope of an inquiry','Collect intake information','Coordinate consultations'],scenario:'A new client wants to book a consultation.'}};
$('#content').innerHTML=`<section id="solutions" class="section wrap"><div class="section-head"><div><p class="eyebrow">01 / WHAT WE HANDLE</p><h2>More than answering.<br>Moving things forward.</h2></div><p>Choose the work you need covered. We shape the team, tools, and workflow around it.</p></div><div class="tabs" role="tablist" aria-label="Solutions">${services.map((s,i)=>`<button role="tab" id="service-tab-${i}" aria-controls="service-panel" aria-selected="${i===0}" data-service="${i}">${s.icon} ${s.name}</button>`).join('')}</div><div id="service-panel" role="tabpanel" class="service-panel"></div></section>
<section class="human-section"><div class="human-photo"><img src="team.png" alt="Illustrative customer operations specialist at a workstation" loading="lazy"></div><div class="human-copy"><p class="eyebrow">TECHNOLOGY WITH A HUMAN CORE</p><h2>Fast when it’s simple.<br>Human when it matters.</h2><p>Some questions need a quick answer. Others need someone who listens. Build an operation with room for both.</p><div class="human-item"><span>✦</span><div><h3>AI handles the repeat work</h3><p>Approved answers, consistent intake, and structured summaries.</p></div></div><div class="human-item"><span>◉</span><div><h3>People own the difficult moments</h3><p>Nuance, judgment, and a handoff that carries the whole story.</p></div></div><button class="btn outline" data-action="demo">See a conversation in action</button></div></section>
<section id="industries" class="section wrap"><div class="section-head"><div><p class="eyebrow">02 / YOUR WORLD, UNDERSTOOD</p><h2>Built around the way<br>your business works.</h2></div><p>A customer's next step looks different in every industry. Your operation should reflect that.</p></div><div class="industry-layout"><div class="industry-nav" role="tablist" aria-label="Industries">${Object.entries(industries).map(([k,v],i)=>`<button role="tab" id="industry-tab-${k}" aria-controls="industry-panel" aria-selected="${i===0}" data-industry="${k}"><span>0${i+1}</span>${v.name}</button>`).join('')}</div><div id="industry-panel" role="tabpanel"></div></div></section>
<section id="how" class="section wrap process"><p class="eyebrow">03 / FROM PLAN TO PERFORMANCE</p><h2>A clear path to your<br>next operation.</h2><div class="steps">${[['01','Map the work','Define channels, coverage, customer needs, and the outcomes that matter.'],['02','Build & connect','Shape the team, prepare your knowledge, and agree the tools and handoffs.'],['03','Train & test','Rehearse real situations and review answers before the operation goes live.'],['04','Launch & improve','Review conversations, coach the team, and refine the workflow together.']].map(s=>`<article><span>${s[0]}</span><h3>${s[1]}</h3><p>${s[2]}</p></article>`).join('')}</div><div class="integrations"><p>YOUR TOOLS. ONE CONNECTED WORKFLOW.</p><div><span>HubSpot</span><span>Zendesk</span><span>Google Workspace</span><span>Salesforce</span><span>Slack</span><span>Calendly</span></div><small>Explore potential integrations during your demo. Availability depends on your setup.</small></div></section>
<section id="plans" class="section light"><div class="wrap"><div class="section-head"><div><p class="eyebrow">04 / FIND YOUR FIT</p><h2>Start with what you need.<br>Grow from there.</h2></div><p>Pick an operating model, then explore your workload. Final scope and pricing are tailored to your requirements.</p></div><div class="plan-grid">${[['Coverage','A flexible front line.','For overflow, after-hours, and changing demand.',['Agreed coverage windows','Shared operation concept','Intake & escalation rules']],['Dedicated','Your team, extended.','For consistent volume and deeper product knowledge.',['Dedicated team concept','Brand & product training','QA and operational reviews']],['AI + Human','One connected operation.','For repeat work at scale, with people ready for complexity.',['AI knowledge & intake','Human escalation design','Workflow & reporting concept']]].map((s,i)=>`<article class="plan ${i===2?'featured':''}"><div class="plan-label">${s[0]} ${i===2?'<span>FRONTLINE APPROACH</span>':''}</div><h3>${s[1]}</h3><p>${s[2]}</p><div class="plan-price">Custom scope<span>Let’s build your requirements</span></div><ul>${s[3].map(x=>`<li>${x}</li>`).join('')}</ul><button class="btn ${i===2?'':'outline'}" data-plan="${s[0]}">Explore ${s[0].toLowerCase()}</button></article>`).join('')}</div><div class="calculator"><div><p class="eyebrow">WORKLOAD EXPLORER</p><h3>What does your month look like?</h3><p>A simple starting point for your discovery call.</p></div><div><label for="volume">Monthly conversations <strong id="volume-value">1,000</strong></label><input id="volume" type="range" min="100" max="5000" step="100" value="1000"><label for="coverage">Coverage preference</label><select id="coverage"><option>Business hours</option><option>After-hours & overflow</option><option>24/7 coverage</option></select></div><div class="calc-result"><span>Illustrative handling workload</span><strong id="hours">100 hours</strong><small>Assumes 6 minutes per conversation. This is not staffing or a price quote.</small><button class="text-button" data-action="book">Discuss these requirements</button></div></div></div></section>
<section class="section wrap"><div class="section-head"><div><p class="eyebrow">05 / VISIBILITY BUILT IN</p><h2>Know what’s happening.<br>Know what comes next.</h2></div><p>Explore a sample client experience: conversations, bookings, quality, and work that needs attention.</p></div><div class="dashboard-preview"><div class="dash-bar"><span class="brand">frontline<span>✳</span></span><span>CLIENT WORKSPACE / SAMPLE DATA</span><button class="btn small outline" data-action="portal">Explore workspace</button></div><div class="metric-grid"><div><span>Conversations handled</span><strong>1,248</strong><small>Across voice, chat & email</small></div><div><span>Appointments booked</span><strong>86</strong><small>Sample monthly outcomes</small></div><div><span>Customer satisfaction</span><strong>94%</strong><small>Illustrative survey result</small></div><div><span>Needs your team</span><strong>12</strong><small>Escalations with context</small></div></div><div class="dash-bottom"><div><p class="eyebrow">CONVERSATION VOLUME</p><div class="bars">${[35,52,43,67,59,81,69,88,78,94,72,83].map((x,i)=>`<div style="height:${x}%"><span>${i+1}</span></div>`).join('')}</div></div><div class="activity"><p class="eyebrow">RECENT OUTCOMES</p><p><span>✓</span> Service visit requested <small>Voice · Intake complete</small></p><p><span>✓</span> Product question resolved <small>Chat · Knowledge answer</small></p><p><span>◉</span> Specialist review needed <small>Email · Context attached</small></p></div></div></div></section>
<section class="section wrap"><div class="section-head"><div><p class="eyebrow">06 / THE WORK IN PRACTICE</p><h2>Small moments.<br>Meaningful outcomes.</h2></div><p>Illustrative scenarios show how an operation can work. Explore the flow for your business.</p></div><div class="story-grid">${[['home','HOME SERVICES','The call after closing.','A homeowner reaches out after hours. Intake collects the details and routes the next step.'],['saas','SOFTWARE & SAAS','The question that needs context.','A customer hits an access problem. Support prepares a clear specialist handover.'],['commerce','ECOMMERCE','The order with an exception.','A shopper needs a return. Policy questions are answered and exceptions reach a person.']].map(x=>`<button class="story" data-story="${x[0]}"><span class="eyebrow">${x[1]} / EXAMPLE</span><h3>${x[2]}</h3><p>${x[3]}</p><span class="story-link">Explore the scenario +</span></button>`).join('')}</div></section>
<section class="section wrap faq"><div><p class="eyebrow">A FEW THINGS YOU MIGHT ASK</p><h2>Clear answers.<br>From the start.</h2><button class="btn outline" data-action="chat">Ask another question</button></div><div>${[['Will customers speak to AI or a person?','The operating model can combine both. Define which questions AI may answer, when a person should take over, and how conversation context travels with them.'],['Can Frontline work with our existing systems?','This concept shows potential connections to CRM, helpdesk, calendar, and messaging tools. A discovery call would confirm your systems and requirements.'],['How is pricing determined?','By service scope, volume, coverage, languages, team model, and integration work. This concept shows options without inventing an approved price.'],['What happens when someone asks for a human?','A live operation should transfer to an available team member or clearly explain the follow-up route. Try the simulated handoff in the chat.'],['What can I try on this website?','Explore services, industries, workload, sample conversations, simulated meeting slots, and a client workspace. No external bookings or CRM actions are created.']].map(x=>`<details><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</div></section>
<section class="cta wrap"><p class="eyebrow">MAKE ROOM FOR WHAT’S NEXT</p><h2>We handle the operation.<br><em>You grow the business.</em></h2><div class="actions"><button class="btn" data-action="book">Let’s build your Frontline</button><button class="btn outline" data-action="demo">Try a conversation</button></div><p>Start with a conversation about your customers and your team.</p></section>`;
function setService(i){if(!Number.isInteger(i)||!services[i])throw new Error('Choose a valid service');const s=services[i];$('#service-panel').setAttribute('aria-labelledby',`service-tab-${i}`);$('#service-panel').innerHTML=`<div><span class="service-icon">${s.icon}</span><h3>${s.tag}</h3><p>${s.desc}</p><button class="btn outline" data-action="book">Discuss ${s.name.toLowerCase()}</button></div><div><p class="eyebrow">WHAT THE WORK CAN INCLUDE</p><ul class="checklist">${s.tasks.map(x=>`<li>${x}</li>`).join('')}</ul><div class="flow">${s.flow.map((x,i)=>`<span><b>0${i+1}</b>${x}</span>`).join('')}</div></div>`;document.querySelectorAll('[data-service]').forEach(b=>{b.setAttribute('aria-selected',String(Number(b.dataset.service)===i));b.tabIndex=Number(b.dataset.service)===i?0:-1});return {service:s.name}}
function setIndustry(k){if(!industries[k])throw new Error('Choose a valid industry');const s=industries[k];$('#industry-panel').setAttribute('aria-labelledby',`industry-tab-${k}`);$('#industry-panel').innerHTML=`<span class="pill">${s.name}</span><h3>${s.label}</h3><p>${s.desc}</p><ul class="checklist">${s.examples.map(x=>`<li>${x}</li>`).join('')}</ul><div class="industry-note"><span>EXAMPLE MOMENT</span><p>${s.scenario}</p><button class="text-button" data-story="${k}">Try this scenario</button></div>`;document.querySelectorAll('[data-industry]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.industry===k));b.tabIndex=b.dataset.industry===k?0:-1});return {industry:s.name}}
setService(0);setIndustry('home');
document.querySelectorAll('[role=tablist]').forEach(list=>list.onkeydown=e=>{const keys=['ArrowRight','ArrowLeft','ArrowDown','ArrowUp','Home','End'];if(!keys.includes(e.key))return;e.preventDefault();const tabs=[...list.querySelectorAll('[role=tab]')];let i=tabs.indexOf(document.activeElement);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1)+tabs.length)%tabs.length;tabs[i].click();tabs[i].focus()});
const modal=$('#modal'),mc=$('#modal-content');let selectedSlot='',selectedDate='',selectedModel='AI + Human';
function openModal(html){mc.innerHTML=html;if(!modal.open)modal.showModal();$('.close').focus()}
$('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
function book(){selectedSlot='';const dates=Array.from({length:3},(_,i)=>{const d=new Date();d.setDate(d.getDate()+i+1);return {id:d.toISOString().slice(0,10),label:d.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})}});selectedDate=dates[0].id;openModal(`<p class="eyebrow">MEET YOUR NEXT OPERATION</p><h2>Let’s find your fit.</h2><p class="muted">Choose a time to preview the booking experience.</p><span class="pill">Simulated booking · No meeting is created</span><form id="booking-form"><label for="model">What are you exploring?</label><select id="model">${['Coverage','Dedicated','AI + Human'].map(x=>`<option ${x===selectedModel?'selected':''}>${x}</option>`).join('')}</select><label>Choose a date</label><div class="date-buttons">${dates.map((x,i)=>`<button type="button" data-date="${x.id}" aria-pressed="${i===0}">${x.label}</button>`).join('')}</div><label for="timezone">Meeting timezone</label><select id="timezone"><option>Tashkent (UTC+5)</option><option>New York</option><option>London</option></select><label>Choose a sample time</label><div class="slot-buttons">${['10:00 AM','1:00 PM','3:30 PM'].map(x=>`<button type="button" data-slot="${x}" aria-pressed="false">${x}</button>`).join('')}</div><button class="btn" id="confirm-booking" disabled>Preview confirmation</button></form>`);$('#booking-form').onsubmit=e=>{e.preventDefault();if(!selectedSlot)return;const zone=$('#timezone').value,model=$('#model').value;openModal(`<div class="success-icon">✓</div><p class="eyebrow">YOUR BOOKING PREVIEW</p><h2>A good next step.</h2><p>${selectedDate} · ${selectedSlot}</p><p>${zone} · ${model}</p><div class="notice">Demonstration complete. No calendar invitation has been created.</div><button class="btn" data-action="close">Keep exploring</button>`)} }
function demo(k='home'){if(!industries[k])k='home';openModal(`<p class="eyebrow">FRONTLINE IN ACTION</p><h2>From question<br>to next step.</h2><p class="muted">An interactive illustration of the AI + human workflow.</p><label for="scenario">Choose an industry</label><select id="scenario">${Object.entries(industries).map(([key,v])=>`<option value="${key}" ${key===k?'selected':''}>${v.name}</option>`).join('')}</select><div id="scenario-story"></div><button class="btn" id="run-demo">Play the conversation</button><button class="btn outline" data-action="chat">Try asking a question</button>`);renderScenario(k);$('#scenario').onchange=e=>renderScenario(e.target.value);$('#run-demo').onclick=()=>{renderScenario($('#scenario').value,true);$('#run-demo').textContent='Replay the conversation'}}
function renderScenario(k,play=false){const v=industries[k],messages=k==='home'?['Can I request a plumbing visit for tomorrow?','I can help with intake. What service do you need and which area are you in?','A leaking kitchen pipe. I’m in the local service area.','I’ll prepare the request for scheduling with these details.']:k==='saas'?['I can’t access my workspace.','Let’s gather the error message and the steps you have tried.','The login keeps redirecting me.','I’ll prepare a technical ticket with the context attached.']:k==='commerce'?['Can I return an item?','I can explain the approved policy and help gather your order details.','My item arrived damaged.','This needs a person to review. I’ll pass along the conversation.']:['I’d like to book a consultation.','What service are you interested in?','Support for our customer inquiries.','I’ll prepare your requirements and show booking options.'];$('#scenario-story').innerHTML=play?`<div class="demo-chat">${messages.map((m,i)=>`<div class="bubble ${i%2===0?'visitor':'assistant'}"><small>${i%2===0?'CUSTOMER':'FRONTLINE'}</small>${m}</div>`).join('')}</div><div class="handoff-card"><strong>Human handoff · simulated</strong><p>Conversation summary, collected requirements, and next action travel together.</p></div>`:`<div class="scenario-intro"><span>THE MOMENT</span><h3>${v.scenario}</h3><p>Watch intake, context gathering, and a clear next step.</p></div>`}
const records=[['Voice','Service visit requested','Intake complete','Service area checked. Request prepared for dispatch.'],['Chat','Product question','Resolved','Approved knowledge answer shared with the customer.'],['Email','Account access','Specialist review','Redirect loop reported. Context ready for technical review.'],['Chat','Return request','Human review','Damaged item reported. Policy exception requires a person.']];
function portal(){openModal(`<p class="eyebrow">CLIENT WORKSPACE / SAMPLE DATA</p><h2>Your operation,<br>in focus.</h2><div class="portal-controls"><label for="portal-filter">Channel</label><select id="portal-filter"><option>All channels</option><option>Voice</option><option>Chat</option><option>Email</option></select><button class="btn small outline" id="export">Export sample report</button></div><div class="metric-grid"><div><span>Handled</span><strong>1,248</strong></div><div><span>Booked</span><strong>86</strong></div><div><span>CSAT</span><strong>94%</strong></div></div><div id="records"></div><p class="muted">Illustrative records only. No customer data or live connection.</p>`);renderRecords();$('#portal-filter').onchange=renderRecords;$('#export').onclick=()=>{const data=records.filter(r=>$('#portal-filter').value==='All channels'||r[0]===$('#portal-filter').value);const csv='Channel,Outcome,Status\n'+data.map(r=>r.slice(0,3).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='frontline-sample-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}
function renderRecords(){const f=$('#portal-filter').value;$('#records').innerHTML=records.filter(r=>f==='All channels'||r[0]===f).map(r=>`<details class="record"><summary><span>${r[0]}</span><strong>${r[1]}</strong><em>${r[2]}</em></summary><p>${r[3]}</p></details>`).join('')}
let chatState={messages:[],handoff:false};function chat(){openModal(`<div class="chat-title"><span class="service-icon">✦</span><div><h3>Ask Frontline</h3><p>Interactive assistant demonstration</p></div></div><div class="notice">Sample responses · No live agent or CRM connection</div><div class="chat-log" id="chat-log" aria-live="polite"></div><div class="chat-quick"><button data-question="What services do you offer?">Explore services</button><button data-question="How does pricing work?">Pricing</button><button data-question="Can I speak to a human?">Human handoff</button><button data-question="I want to book a demo">Book a demo</button></div><form id="chat-form"><label class="sr-only" for="chat-input">Your question</label><input id="chat-input" placeholder="Ask about services, coverage, or booking…" maxlength="500" required autocomplete="off"><button class="btn small" aria-label="Send question">Send</button></form>`);if(!chatState.messages.length)chatState.messages.push({who:'assistant',text:'Hi, I’m your Frontline demo assistant. Ask about services, coverage, pricing, integrations, or a human handoff. You can explore without entering your email.'});renderChat();$('#chat-form').onsubmit=e=>{e.preventDefault();sendChat($('#chat-input').value);$('#chat-input').value=''}}
function renderChat(){const log=$('#chat-log');if(!log)return;log.replaceChildren();chatState.messages.forEach(m=>{const el=document.createElement('div');el.className=`bubble ${m.who==='visitor'?'visitor':'assistant'}`;el.textContent=m.text;log.appendChild(el)});if(chatState.handoff){const h=document.createElement('div');h.className='handoff-card';h.innerHTML='<strong>Sample handoff ready</strong><p>Your question and conversation history would travel to the team. No request is sent in this demo.</p><button class="text-button" data-action="book">Explore a follow-up meeting</button>';log.appendChild(h)}log.scrollTop=log.scrollHeight}
function sendChat(text){text=text.trim();if(!text)return;chatState.messages.push({who:'visitor',text});const q=text.toLowerCase();let a;if(/human|person|agent|handoff/.test(q)){chatState.handoff=true;a='Here is the handoff preview. A live service would transfer to an available team member or explain the follow-up time. This demonstration prepares a summary rather than claiming a live transfer.'}else if(/price|pricing|cost|quote/.test(q)){a='Pricing depends on scope, volume, coverage, languages, and team model. No approved dollar price is available in this demo. Try the workload explorer to prepare requirements.'}else if(/book|meeting|demo|appointment/.test(q)){a='Use Book a demo to choose a sample date and time. The confirmation is simulated; it does not reserve a real calendar slot.'}else if(/24|hour|night|coverage|weekend/.test(q)){a='The concept includes business-hours, after-hours, and 24/7 options. The real agreement would define staffing, channels, availability, and response times.'}else if(/integrat|crm|hubspot|zendesk|calendar|slack/.test(q)){a='Explore possible CRM, helpdesk, calendar, and messaging connections. A discovery call would confirm compatible systems and what data is exchanged. No external system is connected here.'}else if(/service|support|sales|back office|offer|plumb/.test(q)){a='Explore customer experience, sales and intake, back office, and IT support. A home-services flow captures the request, checks the area, and hands context to scheduling or dispatch.'}else if(/data|privacy|security/.test(q)){a='A real operation would agree access, retention, and data handling before launch. This demo keeps the conversation in this page only and does not submit it to a server.'}else{a='I don’t have a reviewed answer for that in this demonstration. Explore the services, preview a human handoff, or choose Book a demo for the next step.'}chatState.messages.push({who:'assistant',text:a});renderChat()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.service!==undefined)setService(Number(b.dataset.service));if(b.dataset.industry)setIndustry(b.dataset.industry);if(b.dataset.plan){selectedModel=b.dataset.plan;book()}if(b.dataset.story)demo(b.dataset.story);if(b.dataset.date){selectedDate=b.dataset.date;document.querySelectorAll('[data-date]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}if(b.dataset.slot){selectedSlot=b.dataset.slot;document.querySelectorAll('[data-slot]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#confirm-booking').disabled=false}if(b.dataset.question)sendChat(b.dataset.question);const a=b.dataset.action;if(a==='book')book();if(a==='demo')demo();if(a==='portal')portal();if(a==='chat')chat();if(a==='close')modal.close()});$('#chat-launch').onclick=chat;
$('.menu').onclick=()=>{const n=$('nav');n.classList.toggle('open');$('.menu').setAttribute('aria-expanded',String(n.classList.contains('open')))};document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{$('nav').classList.remove('open');$('.menu').setAttribute('aria-expanded','false')});
function updateWorkload(){const n=Number($('#volume').value);$('#volume-value').textContent=n.toLocaleString();$('#hours').textContent=`${Math.round(n/10)} hours`;return {monthlyConversations:n,illustrativeHours:Math.round(n/10),coverage:$('#coverage').value}}$('#volume').oninput=updateWorkload;
if(document.modelContext?.registerTool){for(const t of [{name:'select_frontline_service',description:'Select a service in the visible explorer.',inputSchema:{type:'object',properties:{serviceIndex:{type:'integer',minimum:0,maximum:3}},required:['serviceIndex'],additionalProperties:false},execute:i=>setService(i.serviceIndex)},{name:'configure_frontline_workload',description:'Configure the demo workload. Does not submit data or create a quote.',inputSchema:{type:'object',properties:{monthlyConversations:{type:'integer',minimum:100,maximum:5000}},required:['monthlyConversations'],additionalProperties:false},execute:i=>{if(!Number.isInteger(i.monthlyConversations)||i.monthlyConversations<100||i.monthlyConversations>5000||i.monthlyConversations%100)throw new Error('Use 100–5000 in steps of 100');$('#volume').value=String(i.monthlyConversations);return updateWorkload()}}]){try{Promise.resolve(document.modelContext.registerTool({...t,annotations:{readOnlyHint:false,untrustedContentHint:false}})).catch(()=>{})}catch{}}}
